mapper.update:
UPDATE ${msg_table}
SET MSG_STTS_CD = '01',
    GROUP_NO = '${group_no}',
    MDFCN_DT = SYSTIMESTAMP,
    MDFR_ID = #{mod_id}
WHERE ROWID IN (
    SELECT ROWID
    FROM ${msg_table}
    WHERE SNDNG_TYPE_CD = '${msg_type}'
      AND MSG_STTS_CD = '00'
      AND (SNDNG_PRNMNT_YMD < TO_CHAR(SYSDATE, 'YYYYMMDD')
        OR (SNDNG_PRNMNT_YMD = TO_CHAR(SYSDATE, 'YYYYMMDD') AND GDBK_SNDNG_PRNMNT_TM <= TO_CHAR(SYSDATE, 'HH24MISS'))
        ) ORDER BY MOBL_REG_TYPE_CD , SNDNG_PRNMNT_YMD, GDBK_SNDNG_PRNMNT_TM
        FETCH FIRST 500 ROWS ONLY
)

update ${msg_table}
set MSG_STTS_CD = '02',
    ISND_PRCS_DT = SYSTIMESTAMP,
    MDFCN_DT = SYSTIMESTAMP,
    MDFR_ID = #{mod_id}
where GROUP_NO = '${group_no}'

update ${main_table}
set MSG_STTS_CD = '02',
    ISND_PRCS_DT = SYSTIMESTAMP,
    MDFCN_DT = SYSTIMESTAMP,
    MDFR_ID = #{mod_id}
where MSG_MST_NO IN (${strmsgid})

update ${msg_table}
set MSG_STTS_CD = '00',
    GROUP_NO = NULL,
    MDFCN_DT = SYSTIMESTAMP,
    MDFR_ID = #{mod_id}
where GROUP_NO = '${group_no}'
